const items = $input.all();
const result = [];
const today = new Date().toISOString().split('T')[0];

for (const item of items) {
  const data = item.json;
  // Remote OK returns an array; first element is a legal/metadata object
  const jobs = Array.isArray(data) ? data : [data];
  for (const job of jobs) {
    // Skip metadata (has 'legal' field, not 'position')
    if (!job.position || job.legal !== undefined) continue;
    result.push({
      json: {
        job_title: String(job.position || ''),
        company: String(job.company || ''),
        job_url: String(job.url || `https://remoteok.com/remote-jobs/${job.slug || ''}`),
        source: 'Remote OK',
        location_text: String(job.location || 'worldwide'),
        salary: String(job.salary || ''),
        description: String((job.description || '') + ' ' + (Array.isArray(job.tags) ? job.tags.join(' ') : '')),
        posted_date: String(job.date || new Date().toISOString()),
        tags: Array.isArray(job.tags) ? job.tags.join(', ') : '',
        job_id: '',
        date_found: today
      }
    });
  }
}
return result;

