// NOTE: Wellfound requires custom scraping or their API.
// Configure the Fetch Wellfound HTTP node with appropriate auth if using API.
// This normalizer handles a generic JSON array response.
const items = $input.all();
const result = [];
const today = new Date().toISOString().split('T')[0];

for (const item of items) {
  const data = item.json;
  // Try to extract jobs from various possible response shapes
  const jobs = Array.isArray(data) ? data :
                data.jobs ? data.jobs :
                data.data ? (Array.isArray(data.data) ? data.data : []) : [];
  for (const job of jobs) {
    if (!job.title && !job.role) continue;
    result.push({
      json: {
        job_title: String(job.title || job.role || ''),
        company: String(job.company_name || job.company || job.startup_name || ''),
        job_url: String(job.url || job.job_url || ''),
        source: 'Wellfound',
        location_text: String(job.remote ? 'worldwide' : (job.location || 'worldwide')),
        salary: String(job.salary || job.compensation || ''),
        description: String(job.description || job.summary || ''),
        posted_date: String(job.created_at || job.date_posted || new Date().toISOString()),
        tags: Array.isArray(job.skills) ? job.skills.join(', ') : String(job.tags || ''),
