        company: String(job.company_name || job.company || ''),
        job_url: String(job.url || `https://www.workatastartup.com/jobs/${job.id || ''}`),
        source: 'YC Work at Startup',
        location_text: isRemote ? 'worldwide' : String(job.locations || 'unknown'),
