// NOTE: Otta has a private API. You may need to obtain an API key or use their
// public GraphQL endpoint. Adjust the fetch URL accordingly.
const items = $input.all();
const result = [];
const today = new Date().toISOString().split('T')[0];

for (const item of items) {
  const data = item.json;
  const jobs = data.results || data.jobs || (Array.isArray(data) ? data : []);
  for (const job of jobs) {
    if (!job.title) continue;
    const companyName = typeof job.company === 'object' ? (job.company?.name || '') : String(job.company || '');
    const minSalary = job.min_annual_salary || job.salary_min;
    const maxSalary = job.max_annual_salary || job.salary_max;
    const salaryStr = minSalary ? `$${minSalary}${maxSalary ? '-' + maxSalary : '+'}/yr` : '';
    result.push({
      json: {
        job_title: String(job.title || ''),
        company: companyName,
        job_url: String(job.url || `https://app.otta.com/jobs/${job.external_id || job.id || ''}`),
        source: 'Otta',
        location_text: job.remote ? 'worldwide' : String(job.location || 'unknown'),
        salary: salaryStr,
        description: String(job.description || job.summary || ''),
        posted_date: String(job.created_at || new Date().toISOString()),
        tags: Array.isArray(job.skills) ? job.skills.map(s => s.value || s).join(', ') : '',
        job_id: '',
        date_found: today
      }
    });
  }
}
return result;

const jobs = $input.all();

// Load existing job URLs from the Google Sheets read node
let existingUrls = new Set();
let existingKeys = new Set();
try {
  const existingRows = $node['Read Existing Job URLs'].all();
  for (const row of existingRows) {
    if (row.json.job_url) existingUrls.add(String(row.json.job_url).toLowerCase().trim());
    if (row.json.job_title && row.json.company) {
      existingKeys.add(`${String(row.json.company).toLowerCase().trim()}::${String(row.json.job_title).toLowerCase().trim()}`);
    }
  }
} catch(e) {
  // First run or empty sheet - continue with empty sets
}

// Hard reject patterns (must not appear in text without a keep signal)
const REJECT_PATTERNS = [
  /\bus[\s-]?only\b/i,
  /\busa[\s-]?only\b/i,
  /\bunited states only\b/i,
  /\bcanada[\s-]?only\b/i,
  /\buk[\s-]?only\b/i,
  /\beurope[\s-]?only\b/i,
  /\beu[\s-]?only\b/i,
  /\baustralia[\s-]?only\b/i,
  /\bmust be based in\b/i,
  /\bmust live in\b/i,
  /\bmust be located in\b/i,
  /\bmust reside in\b/i,
  /\bauthorized to work in the (us|uk|eu|canada|australia)\b/i,
  /\bwork authorization (in|for) the (us|uk|eu)\b/i,
  /\blocal work permit required\b/i,
  /\bwork permit required\b/i,
  /\bhybrid\b/i,
  /\bonsite\b/i,
  /\bon-site\b/i,
  /\boffice required\b/i,
  /\bin-office\b/i,
  /\bremote within [a-z]+ only\b/i,
  /\bfixed us (business )?hours\b/i,
  /\bfixed eu (business )?hours\b/i,
  /\bno visa sponsorship\b/i,
  /\brelocate to\b/i
];

// Keep signals override some reject patterns
const KEEP_PATTERNS = [
  /worldwide/i,
  /global remote/i,
  /work from anywhere/i,
  /\banywhere\b/i,
  /\bapac\b/i,
  /international contractor/i,
  /accepts? contractors/i,
  /\bcontract(or)?\b/i,
  /\bb2b\b/i,
  /\bdeel\b/i,
  /remote\.com/i,
  /\boyster\b/i,
  /\beor\b/i,
  /employer of record/i,
  /remote.?first/i,
  /distributed team/i,
  /fully (distributed|remote)/i,
  /async/i,
  /asynchronous/i
];

// Keywords that signal this job is in scope by role
const KEYWORD_PATTERNS = [
  /data anal/i, /data scien/i, /business intel/i, /\bbi anal/i,
  /marketing anal/i, /growth anal/i, /ai marketing/i, /ai automation/i,
  /ai workflow/i, /performance marketing/i, /automation special/i,
  /martech/i, /marketing data/i, /remote data/i, /async remote/i,
  /asynchronous remote/i, /worldwide remote/i, /global remote/i,
  /work from anywhere/i, /remote marketing/i, /remote growth/i
];

const seen = new Set([...existingUrls]);
const seenKeys = new Set([...existingKeys]);
const result = [];

for (const item of jobs) {
  const job = item.json;
  if (!job.job_title && !job.job_url) continue;

  const urlKey = String(job.job_url || '').toLowerCase().trim();
  const companyKey = `${String(job.company || '').toLowerCase().trim()}::${String(job.job_title || '').toLowerCase().trim()}`;

  // Deduplicate
  if (urlKey && seen.has(urlKey)) continue;
  if (!urlKey && companyKey !== '::' && seenKeys.has(companyKey)) continue;
  if (urlKey) seen.add(urlKey);
  if (companyKey !== '::') seenKeys.add(companyKey);

  const searchText = [
    job.job_title, job.location_text, job.description, job.tags
  ].join(' ');

  const hasKeepSignal = KEEP_PATTERNS.some(p => p.test(searchText));
  const hasRejectSignal = REJECT_PATTERNS.some(p => p.test(searchText));
  const hasKeyword = KEYWORD_PATTERNS.some(p => p.test(searchText));

  // Reject if hard reject found and no keep signal overrides
  if (hasRejectSignal && !hasKeepSignal) continue;

  // Must have at least a keep signal OR a role keyword to pass
  if (!hasKeepSignal && !hasKeyword) continue;

  job.job_id = urlKey || companyKey;
  result.push({ json: job });
}

return result;

const items = $input.all();
const result = [];

const systemPrompt = `You are filtering remote jobs for Jerry, who lives in Taiwan.

The most important rule: Jerry must be able to work this job while physically based in Taiwan.

Do not pass the job only because it says "remote."

REJECT the job if it:
- Requires the worker to live in the US, Canada, UK, EU, Europe, Australia, or any specific country outside Taiwan
- Requires local work authorization outside Taiwan
- Is hybrid, onsite, or remote within one country only
- Requires fixed working hours that would force Jerry to work through the night in Taiwan (Taiwan is UTC+8; US EST is UTC-5, which means 9am EST = 10pm Taiwan)

KEEP the job only if one of these is true:
- The job says worldwide remote
- The job says work from anywhere
- The job says global remote
- The job says APAC remote or APAC friendly
- The job allows international contractors
- The job accepts people based anywhere
- The company hires through EOR, Deel, Remote.com, Oyster, or a contractor agreement

Return ONLY valid JSON with no markdown, no explanation:
{
  "taiwan_eligible": "yes/no/unclear",
  "reason": "one short sentence",
  "location_risk": "low/medium/high",
  "timezone_risk": "low/medium/high",
  "contractor_possible": "yes/no/unclear",
  "decision": "keep/reject/manual_check"
}`;

for (const item of items) {
  const job = item.json;
  // Truncate description to avoid token limits
  const desc = String(job.description || '').substring(0, 3000);
  const jobSnippet = `Job Title: ${job.job_title}\nCompany: ${job.company}\nLocation: ${job.location_text}\nSalary: ${job.salary}\nTags: ${job.tags}\n\nDescription:\n${desc}`;

  result.push({
    json: {
      ...job,
      _ai_prompt: systemPrompt,
      _ai_job_text: jobSnippet,
      _request_body: JSON.stringify({
        model: 'claude-sonnet-4-6',
        max_tokens: 300,
        messages: [
          { role: 'user', content: systemPrompt + '\n\nJob post:\n' + jobSnippet }
        ]
      })
    }
  });
}

return result;

const items = $input.all();
const result = [];

const ASYNC_HIGH = [/\basync\b/i, /\basynchronous\b/i, /\bno required meetings\b/i, /\blow meeting culture\b/i];
const ASYNC_MED = [/\bflexible hours\b/i, /\bflexible schedule\b/i, /\bdistributed team\b/i, /\bwork across time zones\b/i, /\bown your schedule\b/i, /\bself.directed\b/i];
const ASYNC_LOW_OK = [/\bremote.?first\b/i, /\bfully remote\b/i, /\bwork from anywhere\b/i, /\basync.?friendly\b/i];
const ASYNC_REJECT = [/\bstrict 9.to.5\b/i, /\bfixed.{1,10}(est|pst|cet|gmt).{1,10}hours\b/i, /\bfixed us (business )?hours\b/i, /\bdaily live calls required\b/i, /\bmust overlap.*full business day\b/i, /\bonsite\b/i, /\bhybrid\b/i];

const ROLE_HIGH = [/data anal/i, /data scien/i, /business intel/i, /\bbi anal/i, /marketing anal/i, /performance marketing anal/i, /growth anal/i, /ai marketing/i, /ai automation/i, /ai workflow/i, /automation special/i, /martech anal/i];
const ROLE_MED = [/analyst/i, /data/i, /marketing/i, /growth hacker/i, /analytics/i, /insights/i, /reporting/i, /digital marketing/i, /creative strateg/i, /seo/i, /ppc/i, /paid media/i];

for (const item of items) {
  const job = item.json;
  // Parse Claude API response
  let aiResult = { taiwan_eligible: 'unclear', reason: 'No AI response', location_risk: 'medium', timezone_risk: 'medium', contractor_possible: 'unclear', decision: 'manual_check' };
  try {
    const apiResponse = item.json;
    // The HTTP response comes back as the new item data; original job fields are lost
    // We need to find the AI text content
    const content = apiResponse.content;
    if (Array.isArray(content) && content[0] && content[0].text) {
      const raw = content[0].text.trim();
      const jsonMatch = raw.match(/\{[\s\S]*\}/);
      if (jsonMatch) {
        aiResult = JSON.parse(jsonMatch[0]);
      }
    }
  } catch(e) {
    // keep default aiResult
  }

  // Re-attach original job data from the stored fields
  const jobData = {
    date_found: job.date_found || job._date_found,
    job_title: job.job_title || job._job_title,
    company: job.company || job._company,
    job_url: job.job_url || job._job_url,
    source: job.source || job._source,
    location_text: job.location_text || job._location_text,
    salary: job.salary || job._salary,
    description: job.description || job._description,
    posted_date: job.posted_date || job._posted_date,
    tags: job.tags || job._tags,
    job_id: job.job_id || job._job_id
  };

  // If AI hard rejects, push to result with score 0
  if (aiResult.decision === 'reject' || aiResult.taiwan_eligible === 'no') {
    result.push({
      json: {
        ...jobData,
        taiwan_eligible: 'no',
        taiwan_reason: aiResult.reason || 'AI rejected',
        location_risk: aiResult.location_risk || 'high',
        timezone_risk: aiResult.timezone_risk || 'high',
        contractor_possible: aiResult.contractor_possible || 'no',
        async_level: 'unknown',
        role_category: 'unknown',
        score: 0,
        why_good_fit: '',
        _decision: 'reject',
        application_status: '',
        notes: ''
      }
    });
    continue;
  }

  const desc = String(jobData.description || '').toLowerCase();
  const titleTags = (String(jobData.job_title || '') + ' ' + String(jobData.tags || '')).toLowerCase();
  const fullText = desc + ' ' + titleTags + ' ' + String(jobData.location_text || '').toLowerCase();

  // Async filter
  const asyncReject = ASYNC_REJECT.some(p => p.test(fullText));
  const asyncHigh = ASYNC_HIGH.some(p => p.test(fullText));
  const asyncMed = ASYNC_MED.some(p => p.test(fullText));
  const asyncLowOk = ASYNC_LOW_OK.some(p => p.test(fullText));

  let asyncLevel;
  if (asyncHigh) asyncLevel = 'high';
  else if (asyncMed) asyncLevel = 'medium';
  else if (asyncLowOk) asyncLevel = 'low';
  else asyncLevel = 'unknown';

  // Hard reject on bad async signals
  if (asyncReject && !asyncHigh && !asyncMed) {
    result.push({
      json: {
        ...jobData,
        taiwan_eligible: aiResult.taiwan_eligible || 'unclear',
        taiwan_reason: aiResult.reason || '',
        location_risk: aiResult.location_risk || 'medium',
        timezone_risk: 'high',
        contractor_possible: aiResult.contractor_possible || 'unclear',
        async_level: 'low',
        role_category: 'unknown',
        score: 0,
        why_good_fit: '',
        _decision: 'reject',
        application_status: '',
        notes: 'Rejected: fixed hours incompatible with Taiwan'
      }
    });
    continue;
  }

  // Scoring
  let score = 0;
  const eligible = aiResult.taiwan_eligible || 'unclear';
  const locRisk = aiResult.location_risk || 'medium';
  const tzRisk = aiResult.timezone_risk || 'medium';

  // Taiwan eligibility score (40 max)
  if (eligible === 'yes' && locRisk === 'low') score += 40;
  else if (eligible === 'yes') score += 30;
  else if (/apac/i.test(fullText)) score += 30;
  else if (eligible === 'unclear' && locRisk !== 'high') score += 20;
  else score += 0;

  // Async score (25 max)
  if (asyncLevel === 'high') score += 25;
  else if (asyncLevel === 'medium') score += 20;
  else if (asyncLevel === 'low') score += 15;
  else if (asyncLowOk) score += 10;

  // Role fit score (25 max)
  let roleCategory = 'other';
  if (ROLE_HIGH.some(p => p.test(titleTags))) {
    score += 25;
    roleCategory = 'high_fit';
  } else if (ROLE_MED.some(p => p.test(titleTags))) {
    score += 15;
    roleCategory = 'adjacent';
  }

  // Salary score (25 max)
  const salaryStr = String(jobData.salary || '');
  if (salaryStr) {
    const nums = salaryStr.replace(/[^0-9]/g, ' ').trim().split(/\s+/).map(Number).filter(n => n > 0);
    if (nums.length > 0) {
      const biggest = Math.max(...nums);
      // Detect if annual (>20000) and convert to monthly
      const monthly = biggest > 20000 ? biggest / 12 : biggest;
      if (monthly >= 5000) score += 25;
      else if (monthly >= 3000) score += 15;
      else score += 10;
    } else {
      score += 10; // Salary mentioned, couldn't parse
    }
  }

  score = Math.min(score, 100);

  // One sentence rule final check
  // "I can do this job while living in Taiwan, without moving, without foreign work auth, and without destroying my sleep schedule."
  const passesRule = eligible !== 'no' && locRisk !== 'high' && tzRisk !== 'high';

  let finalDecision;
  if (!passesRule || score < 70) finalDecision = 'reject';
  else if (aiResult.decision === 'manual_check' || eligible === 'unclear' || locRisk === 'medium') finalDecision = 'manual_check';
  else finalDecision = 'keep';

  const whyFit = [];
  if (eligible === 'yes') whyFit.push('Taiwan eligible');
  if (asyncLevel === 'high') whyFit.push('Fully async');
  else if (asyncLevel === 'medium') whyFit.push('Flexible schedule');
  if (roleCategory === 'high_fit') whyFit.push('Strong role match for Jerry (data/AI/marketing)');
  else if (roleCategory === 'adjacent') whyFit.push('Adjacent role');
  if (salaryStr) whyFit.push('Salary listed');
  if (/deel|remote\.com|oyster|eor|employer of record/i.test(fullText)) whyFit.push('EOR/contractor friendly');

  result.push({
    json: {
      ...jobData,
      taiwan_eligible: eligible,
      taiwan_reason: aiResult.reason || '',
      location_risk: locRisk,
      timezone_risk: tzRisk,
      contractor_possible: aiResult.contractor_possible || 'unclear',
      async_level: asyncLevel,
      role_category: roleCategory,
      score,
      why_good_fit: whyFit.join('; '),
      _decision: finalDecision,
      application_status: 'new',
      notes: ''
    }
  });
}

return result;

const items = $input.all();
const result = [];

const JERRY_BIO = `Jerry is based in Taiwan. Background:
- Bilingual English and Mandarin (grew up in California and Taiwan)
- Digital marketing background
- Data science bootcamp experience
- Technical skills: Python, SQL, Tableau, Power BI
- Marketing skills: Performance marketing, SEO, PPC, GA4, Meta Ads, Google Ads
- AI tools: ChatGPT, Claude, Gemini, Cursor
- Projects: dashboards, EDA, machine learning, customer segmentation, fraud detection, marketing analytics
- Available: immediately, works async, Taiwan time (UTC+8)`;

for (const item of items) {
  const job = item.json;
  const prompt = `Write a short, punchy cover letter for Jerry applying to this role.

Jerry wants async global remote work and is based in Taiwan.

${JERRY_BIO}

Job:
Title: ${job.job_title}
Company: ${job.company}
Description: ${String(job.description || '').substring(0, 2000)}

Instructions:
- Under 220 words
- Tone: confident, direct, human, not desperate
- Open strong, no "I am writing to apply..."
- Mention specifically how Jerry can help this company:
  - Reduce manual analysis time
  - Improve reporting speed
  - Connect marketing and data
  - Build AI-assisted workflows
  - Turn messy data into business action
- Mention Taiwan / async briefly but don't dwell on it
- End with a clear CTA
- No sign-off needed

Return only the cover letter text, no subject line, no JSON.`;

  result.push({
    json: {
      ...job,
      _cover_letter_request: JSON.stringify({
        model: 'claude-sonnet-4-6',
        max_tokens: 600,
        messages: [{ role: 'user', content: prompt }]
      })
    }
  });
}
return result;

