const items = $input.all();

// Collect all processed jobs from previous nodes
let allJobs = [];
try { allJobs = allJobs.concat($node['Append to Filtered Jobs'].all().map(i => i.json)); } catch(e) {}
try { allJobs = allJobs.concat($node['Append to Rejected Jobs'].all().map(i => i.json)); } catch(e) {}
// If the above didn't work, use items from the merge node
if (allJobs.length === 0) {
  allJobs = items.map(i => i.json);
}

const kept = allJobs.filter(j => j._decision === 'keep' || j._decision === 'manual_check');
const rejected = allJobs.filter(j => j._decision === 'reject' || j.score === 0);

const topJobs = kept
  .filter(j => j._decision === 'keep')
  .sort((a, b) => (b.score || 0) - (a.score || 0))
  .slice(0, 10);

const manualCheck = kept
  .filter(j => j._decision === 'manual_check')
  .sort((a, b) => (b.score || 0) - (a.score || 0))
  .slice(0, 5);

// Rejection reasons
const reasons = { us: 0, eu: 0, hybrid: 0, timezone: 0, other: 0 };
for (const j of rejected) {
  const r = String(j.taiwan_reason || j.notes || '').toLowerCase();
  if (/us.only|usa|united states/i.test(r)) reasons.us++;
  else if (/eu.only|europe|uk.only|canada/i.test(r)) reasons.eu++;
  else if (/hybrid|onsite/i.test(r)) reasons.hybrid++;
  else if (/timezone|fixed hours|est|pst|cet/i.test(r)) reasons.timezone++;
  else reasons.other++;
}

const date = new Date().toLocaleDateString('en-US', {
  weekday: 'long', year: 'numeric', month: 'long', day: 'numeric',
  timeZone: 'Asia/Taipei'
});

let msg = `DAILY TAIWAN ELIGIBLE ASYNC REMOTE JOBS\n`;
msg += `${date}\n`;
msg += `${'='.repeat(50)}\n\n`;

if (topJobs.length === 0) {
  msg += `No new qualifying jobs found today.\n\n`;
} else {
  msg += `TOP JOBS TODAY (${topJobs.length} jobs scoring 70+)\n`;
  msg += `${'─'.repeat(40)}\n\n`;
  topJobs.forEach((j, i) => {
    msg += `${i + 1}. ${j.job_title}\n`;
    msg += `   Company: ${j.company || 'Unknown'}\n`;
    msg += `   Score: ${j.score}/100${j.score >= 85 ? ' *** HIGH PRIORITY ***' : ''}\n`;
    msg += `   Taiwan eligible: ${j.taiwan_eligible}\n`;
    msg += `   Reason: ${j.taiwan_reason || 'N/A'}\n`;
    msg += `   Async level: ${j.async_level}\n`;
    msg += `   Timezone risk: ${j.timezone_risk}\n`;
    msg += `   Salary: ${j.salary || 'Not listed'}\n`;
    msg += `   Why it fits Jerry: ${j.why_good_fit || 'Role and location match'}\n`;
    msg += `   Apply: ${j.job_url}\n\n`;
  });
}

if (manualCheck.length > 0) {
  msg += `MANUAL CHECK REQUIRED (${manualCheck.length} jobs)\n`;
  msg += `${'─'.repeat(40)}\n`;
  msg += `(Taiwan eligibility is unclear but score is high — review before applying)\n\n`;
  manualCheck.forEach((j, i) => {
    msg += `${i + 1}. ${j.job_title} at ${j.company || 'Unknown'}\n`;
    msg += `   Score: ${j.score}/100 | Location risk: ${j.location_risk}\n`;
    msg += `   Note: ${j.taiwan_reason || 'Unclear eligibility — check manually'}\n`;
    msg += `   Apply: ${j.job_url}\n\n`;
  });
}

msg += `REJECTED SUMMARY\n`;
msg += `${'─'.repeat(40)}\n`;
msg += `  US only: ${reasons.us}\n`;
msg += `  EU/UK/Canada only: ${reasons.eu}\n`;
msg += `  Hybrid or onsite: ${reasons.hybrid}\n`;
msg += `  Timezone incompatible: ${reasons.timezone}\n`;
msg += `  Other reasons: ${reasons.other}\n`;
msg += `  Total rejected: ${rejected.length}\n\n`;

msg += `STATS\n`;
msg += `${'─'.repeat(40)}\n`;
msg += `  Total new jobs found: ${allJobs.length}\n`;
msg += `  Qualifying (70+): ${topJobs.length}\n`;
msg += `  Manual review: ${manualCheck.length}\n`;
msg += `  High priority (85+): ${topJobs.filter(j => (j.score || 0) >= 85).length}\n`;
msg += `  Cover letters drafted: ${topJobs.filter(j => (j.score || 0) >= 85).length}\n`;

return [{ json: { subject: `Taiwan Job Hunter: ${topJobs.length} jobs found (${date})`, body: msg, job_count: topJobs.length } }];
